const input = $json.body ?? $json;
if (input.workflowKey !== "anc.ancfz.int.06.request" || input.contract !== "omnichannel-intent-v1") throw new Error('Workflow contract mismatch.');
if (typeof input.tenantId !== 'string' || typeof input.sessionId !== 'string' || typeof input.actionId !== 'string' || typeof input.eventId !== 'string' || typeof input.correlationId !== 'string' || !Number.isInteger(input.attempt) || input.attempt < 1) throw new Error('Server-issued action, tenant, event, correlation and attempt references are required.');
return [{ json: { ...input, workflowKey: "anc.ancfz.int.06.request", contract: "omnichannel-intent-v1" } }];

const lead = $json.lead;
if (!lead || typeof lead.id !== 'string' || typeof lead.actionId !== 'string' || typeof lead.tenantId !== 'string') throw new Error('Expected authorized internal CRM lead response.');
const remoteVerified = typeof lead.leadId === 'string' && lead.leadId.length > 0 && typeof lead.remoteCrm === 'string' && lead.remoteCrm.length > 0;
return [{ json: { actionId: lead.actionId, tenantId: lead.tenantId, state: remoteVerified ? 'completed' : 'failed', ...(remoteVerified ? { externalReference: 'crm-lead-' + lead.id } : {}) } }];
